      const sendcloudOrder:any={_zenvia_weight:{source:'manual',estimated:false},order_id:externalId,order_number:orderNumber,order_details:{integration:{id:integrationId},status:{code:'unshipped',message:'Unshipped'},order_created_at:now,order_items:items},payment_details:{total_price:{value:total,currency:'EUR'},status:{code:'paid',message:'Paid'}},shipping_address:{name:customerName,company_name:clean(manual.companyName)||null,address_line_1:address,house_number:clean(manual.houseNumber)||null,address_line_2:clean(manual.address2)||null,postal_code:postalCode,city,country_code:countryCode,email:clean(manual.email)||null,phone_number:clean(manual.phone)||null},shipping_details:{is_local_pickup:false,delivery_indicator:'Pedido manual ZENVIA Gestión',measurement:{weight:{value:weight,unit:'kg'}}}};
